#define main inherited_graph_main
#include "one_layer_graph_test.cpp"
#undef main
#include "softmax_projection_probe.h"
#include "probability_contract.h"
// Host-only source-model boundary: no DSP implementation is called here.
int main(int argc,char** argv){if(argc!=2)return 1;auto fs=one::read(argv[1]);auto cs=segmentstudy::lnCases(fs),gs=upstreamreference::fullUpstream(fs);std::vector<std::map<std::string,one::Vec>> gr;for(auto& z:gs)gr.push_back(one::reference(z,true));double pError=0,rowError=0,dsBound=0,dvBound=0,dsError=0,dvError=0;unsigned bad=0,count=0;for(auto& z:cs){auto c=one::lncase(z);c.x=z.v.at("layerinput");c.gamma=z.v.at("gamma1");c.beta=z.v.at("beta1");auto ln=mmfixture::ln::doubleReference(c,64);auto host=mmfixture::ln::anchoredFp32Oracle(c,64);one::Vec q[2],f[2];for(unsigned j=0;j<2;++j){auto& w=z.v.at(j?"wk":"wq");q[j]=one::mm(ln.y,one::d(w),32,64,64);f[j]=one::mm(one::d(host.y),one::d(w),32,64,64,false,false,true);}for(unsigned h=0;h<2;++h){auto raw=one::mm(one::split(q[0],h),one::split(q[1],h),32,32,32,false,true),rf=one::mm(one::split(f[0],h),one::split(f[1],h),32,32,32,false,true,true);auto scaled=one::mul(raw,{double(probabilitycontract::scale())}),sf=one::mul(rf,{double(probabilitycontract::scale())},true);auto masked=probabilitycontract::masked(scaled),mf=probabilitycontract::masked(sf,true);auto p=one::softmax(masked),pf=one::softmax(mf,true);double err=0,rows=0;for(unsigned r=0;r<32;++r){double sum=0;for(unsigned col=0;col<32;++col){unsigned i=r*32+col;err=std::max(err,std::fabs(p[i]-pf[i]));sum+=pf[i];if(!std::isfinite(pf[i])||pf[i]<0||(col>r&&pf[i]!=0))return 2;}rows=std::max(rows,std::fabs(sum-1));}pError=std::max(pError,err);rowError=std::max(rowError,rows);bad+=err>probabilitycontract::pGate||rows>probabilitycontract::rowGate;for(auto& a:gr){auto key="h"+std::to_string(h)+"_";auto b=probabilitycontract::impact(a.at(key+"dp"),a.at(key+"dc"),p,pf);dsBound=std::max(dsBound,b.first);dvBound=std::max(dvBound,b.second);bad+=b.first>probabilitycontract::dsGate/8||b.second>probabilitycontract::dvGate/10;auto ds=probabilitycontract::backward(a.at(key+"dp"),p),df=probabilitycontract::backward(a.at(key+"dp"),pf,true);auto dv=one::mm(p,a.at(key+"dc"),32,32,32,true),vf=one::mm(pf,a.at(key+"dc"),32,32,32,true,false,true);for(unsigned i=0;i<1024;++i){dsError=std::max(dsError,std::fabs(ds[i]-df[i]));dvError=std::max(dvError,std::fabs(dv[i]-vf[i]));}}++count;}}
 std::printf("probability_reference_host,cases=%zu,heads=%u,gradient_cases=%zu,cartesian_boundary=1,p_maxAbs=%.15g,row_error=%.15g,ds_bound=%.15g,dv_bound=%.15g,ds_actual=%.15g,dv_actual=%.15g,joint_failures=%u,dsp_claim=0\n",cs.size(),count,gr.size(),pError,rowError,dsBound,dvBound,dsError,dvError,bad);return bad?4:0;
}
